import {emptyState,shuffle,filterQuestions,validateBank,validateState} from './core.js';
const $=id=>document.getElementById(id), KEY='store-it-quiz-v1';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let bank=[],state=emptyState(),session=null,selection=null,installPrompt;
function notice(message){$('notice').textContent=message;}
function save(){state.session=session;try{localStorage.setItem(KEY,JSON.stringify(state));}catch{notice('履歴を保存できません。ブラウザーの保存設定を確認するか、履歴を書き出してください。');}}
const byId=id=>bank.find(q=>q.id===id);
function candidates(){return filterQuestions(bank,state,$('category').value,$('mode').value);}
function update(){const answered=new Set(state.answers.map(a=>a.id));$('attempted').textContent=`${answered.size} / ${bank.length}`;$('rate').textContent=state.answers.length?`${Math.round(state.answers.filter(a=>a.correct).length/state.answers.length*100)}%`:'—';$('coverage').value=answered.size/bank.length*100;$('available').textContent=`出題対象 ${candidates().length} 問`;$('start').disabled=!candidates().length;$('bankInfo').textContent=`全${bank.length}問・${new Set(bank.map(q=>q.category)).size}分野`;$('resume').hidden=!session;$('categoryStats').innerHTML=[...new Set(bank.map(q=>q.category))].map(cat=>{const qs=bank.filter(q=>q.category===cat);return `<div class="category-item"><span>${esc(cat)}</span><span>${qs.filter(q=>answered.has(q.id)).length} / ${qs.length}問 回答済み</span></div>`;}).join('');$('history').innerHTML='<h3>最近の回答（最大30件）</h3>'+(state.answers.slice(-30).reverse().map(a=>`<div class="history-item"><strong>${a.correct?'正解':'不正解'} · ${esc(byId(a.id)?.prompt||a.id)}</strong><small>${esc(new Date(a.at).toLocaleString('ja-JP'))}</small></div>`).join('')||'<p>回答すると、ここに履歴が残ります。</p>');}
function start(ids){if(session&&!confirm('進行中の問題セットを終了して、新しく始めますか？ 回答済みの履歴は残ります。'))return;let selected=ids?ids.map(byId).filter(Boolean):candidates();if(!selected.length){notice('対象の問題がありません。出題条件を変更してください。');return;}if($('shuffle').checked)selected=shuffle(selected);const n=ids?selected.length:$('count').value==='all'?selected.length:Number($('count').value);session={ids:selected.slice(0,n).map(q=>q.id),index:0,results:[],order:shuffle([0,1,2,3])};selection=null;notice('');save();update();render();$('work').scrollIntoView({behavior:'auto',block:'start'});}
function render(){if(!session)return;notice('');const q=byId(session.ids[session.index]);if(!q)return finish();const result=session.results[session.index];selection=result?.choice??null;$('work').innerHTML=`<div class="qtop"><span class="pill">${esc(q.category)} · ${session.index+1} / ${session.ids.length}問</span><button id="star" aria-pressed="${state.bookmarks.includes(q.id)}">${state.bookmarks.includes(q.id)?'★ 登録済み':'☆ お気に入り'}</button></div><progress value="${session.index}" max="${session.ids.length}" aria-label="このセットの進み具合"></progress><h2 class="question" tabindex="-1">${esc(q.prompt)}</h2><div class="choices" role="group" aria-label="選択肢">${session.order.map((original,i)=>`<button class="choice ${result?(original===q.answer?'correct':original===result.choice?'wrong':''):''}" data-choice="${original}" ${result?'disabled':''} aria-pressed="${selection===original}"><b>${'ABCD'[i]}</b><span>${esc(q.choices[original])}${result&&original===q.answer?'（正解）':''}</span></button>`).join('')}</div><div id="feedback" aria-live="polite">${result?feedback(q,result):''}</div><div class="actions">${result?'<button class="primary" id="next">'+(session.index+1===session.ids.length?'結果を見る':'次の問題')+'</button>':'<button class="primary" id="submit" disabled>回答する</button>'}<button id="pause">中断して保存</button></div>`;$('star').onclick=()=>{state.bookmarks=state.bookmarks.includes(q.id)?state.bookmarks.filter(id=>id!==q.id):[...state.bookmarks,q.id];save();update();$('star').textContent=state.bookmarks.includes(q.id)?'★ 登録済み':'☆ お気に入り';$('star').setAttribute('aria-pressed',String(state.bookmarks.includes(q.id)));};document.querySelectorAll('[data-choice]').forEach(btn=>btn.onclick=()=>{selection=Number(btn.dataset.choice);document.querySelectorAll('[data-choice]').forEach(b=>{b.classList.toggle('selected',b===btn);b.setAttribute('aria-pressed',String(b===btn));});$('submit').disabled=false;});if($('submit'))$('submit').onclick=answer;if($('next'))$('next').onclick=()=>{session.index++;session.order=shuffle([0,1,2,3]);save();render();};$('pause').onclick=()=>{save();$('work').innerHTML='<div class="section-label">SAVED</div><h2>続きは、いつでも。</h2><p>回答と進み具合を保存しました。「中断した学習を再開」から続けられます。</p>';update();};$('work').querySelector('h2')?.focus({preventScroll:true});}
function feedback(q,r){return `<div class="feedback"><h3>${r.correct?'正解です':'もう一度、理由を確認しましょう'}</h3><p><strong>正解：${esc(q.choices[q.answer])}</strong></p><p>${esc(q.explanation)}</p></div>`;}
function answer(){if(selection===null||!session||session.results[session.index])return;const q=byId(session.ids[session.index]);const r={id:q.id,choice:selection,correct:selection===q.answer,at:new Date().toISOString()};session.results.push(r);state.answers.push(r);save();update();render();$('next').focus();}
function finish(){const results=[...session.results],correct=results.filter(r=>r.correct).length;session=null;notice('');save();update();$('work').innerHTML=`<div class="section-label">SESSION COMPLETE</div><h2>おつかれさまでした。</h2><div class="score">${correct}<small> / ${results.length}問</small></div><p>今回の正答率 ${Math.round(correct/results.length*100)}%。解説を振り返って、理解を積み重ねましょう。</p><div class="actions"><button id="again" class="primary">同じ問題をもう一度</button>${correct<results.length?'<button id="retry">間違えた問題だけ復習</button>':''}</div>${results.map(r=>{const q=byId(r.id);return `<details class="review"><summary>${r.correct?'○':'×'} ${esc(q.prompt)}</summary><p>あなたの回答：${esc(q.choices[r.choice])}</p><p>正解：${esc(q.choices[q.answer])}</p><p>${esc(q.explanation)}</p></details>`;}).join('')}`;$('again').onclick=()=>start(results.map(r=>r.id));if($('retry'))$('retry').onclick=()=>start(results.filter(r=>!r.correct).map(r=>r.id));}
async function init(){try{bank=validateBank(await (await fetch('./questions.json')).json());}catch{notice('問題集を読み込めません。オンラインで再読み込みしてください。ローカルで使う場合は「起動.cmd」を使ってください。');$('start').disabled=true;return;}try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw){state=validateState(raw,bank);const s=raw.session;if(s&&Array.isArray(s.ids)&&s.ids.length&&s.ids.every(id=>byId(id))&&Number.isInteger(s.index)&&s.index>=0&&s.index<s.ids.length&&Array.isArray(s.results)&&s.results.length>=s.index&&s.results.length<=s.index+1&&Array.isArray(s.order)&&s.order.length===4&&[0,1,2,3].every(n=>s.order.includes(n))){const checked=validateState({version:1,answers:s.results,bookmarks:[]},bank);if(checked.answers.length===s.results.length&&checked.answers.every((r,i)=>r.id===s.ids[i]))session={ids:s.ids,index:s.index,results:checked.answers,order:s.order};}}}catch{notice('保存済み履歴を読み込めませんでした。必要ならバックアップを読み込んでください。');}for(const cat of [...new Set(bank.map(q=>q.category))])$('category').add(new Option(cat,cat));$('start').onclick=()=>start();$('resume').onclick=render;['category','mode'].forEach(id=>$(id).onchange=update);$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({...state,session:null},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`店舗IT学習履歴_${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>15000000)throw Error('ファイルが大きすぎます');const imported=validateState(JSON.parse(await file.text()),bank);if(confirm('現在の履歴を、ファイルの内容に置き換えますか？')){state=imported;session=null;notice('');save();update();$('work').innerHTML='<h2>履歴を読み込みました。</h2><p>出題条件を選んで学習を始められます。</p>';notice('履歴を読み込みました。');}}catch(err){notice(`読み込めませんでした：${err.message}`);}e.target.value='';};$('reset').onclick=()=>{if(confirm('この端末の回答履歴・お気に入り・中断データを削除しますか？')){state=emptyState();session=null;save();location.reload();}};$('refresh').onclick=async()=>{if(session){notice('中断データは保存済みです。更新後は「再開」から続けられます。');}try{const reg=await navigator.serviceWorker?.getRegistration();await reg?.update();location.reload();}catch{notice('更新を確認できません。オンラインで再度お試しください。');}};update();if(session)notice('中断した問題セットがあります。「再開」から続けられます。');setupPwa();const ctx=document.modelContext;if(ctx?.registerTool)Promise.resolve(ctx.registerTool({name:'read_quiz_progress',description:'端末内のクイズ学習進捗を取得する',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw Error('入力は空のオブジェクトにしてください');return {questions:bank.length,answered:new Set(state.answers.map(a=>a.id)).size,attempts:state.answers.length};}})).catch(()=>{});}
function setupPwa(){if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>$('offlineState').textContent='オフライン学習の準備ができました。最新版の取得には通信が必要です。').catch(()=>$('offlineState').textContent='この環境ではオフライン機能を準備できませんでした。HTTPSまたはlocalhostで開いてください。');}else $('offlineState').textContent='このブラウザーではオフライン機能を利用できません。';}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false;});$('install').onclick=async()=>{await installPrompt?.prompt();installPrompt=null;$('install').hidden=true;};window.addEventListener('appinstalled',()=>$('install').hidden=true);function network(){$('network').textContent=navigator.onLine?'オンライン':'オフライン';}window.addEventListener('online',network);window.addEventListener('offline',network);network();init();
